1|import "server-only";
2|import { notFound } from "next/navigation";
3|import { library } from "@/core/library";
4|import type { AnalyzedScene, Book } from "@/core/types";
5|
6|export interface BookPayload {
7|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">;
8|  scenes: AnalyzedScene[];
9|}
10|
11|// Joins one book's two JSON chunks. The import() calls stay inline in
12|// LOADERS below so the bundler sees each book as its own chunk.
13|async function pair(
14|  book: Promise<{ default: unknown }>,
15|  analysis: Promise<{ default: unknown }>,
16|): Promise<BookPayload> {
17|  const [b, a] = await Promise.all([book, analysis]);
18|  return {
19|    book: b.default as BookPayload["book"],
20|    scenes: (a.default as { scenes: AnalyzedScene[] }).scenes,
21|  };
22|}
23|
24|// One lazy entry per processed book: a route loads only its own book,
25|// and unknown ids simply miss the map, so traversal input can never
26|// name a file. One entry per book; the pipeline adds the rest.
27|const LOADERS: Record<string, () => Promise<BookPayload>> = {
28|  oz: () => pair(import("../data/books/oz/book.json"), import("../data/books/oz/analysis.json")),
29|  alice: () =>
30|    pair(import("../data/books/alice/book.json"), import("../data/books/alice/analysis.json")),
31|  carol: () =>
32|    pair(import("../data/books/carol/book.json"), import("../data/books/carol/analysis.json")),
33|  dracula: () =>
34|    pair(import("../data/books/dracula/book.json"), import("../data/books/dracula/analysis.json")),
35|  frankenstein: () =>
36|    pair(
37|      import("../data/books/frankenstein/book.json"),
38|      import("../data/books/frankenstein/analysis.json"),
39|    ),
40|  jungle: () =>
41|    pair(import("../data/books/jungle/book.json"), import("../data/books/jungle/analysis.json")),
42|  peterpan: () =>
43|    pair(
44|      import("../data/books/peterpan/book.json"),
45|      import("../data/books/peterpan/analysis.json"),
46|    ),
47|  pride: () =>
48|    pair(import("../data/books/pride/book.json"), import("../data/books/pride/analysis.json")),
49|  sherlock: () =>
50|    pair(
51|      import("../data/books/sherlock/book.json"),
52|      import("../data/books/sherlock/analysis.json"),
53|    ),
54|  treasure: () =>
55|    pair(
56|      import("../data/books/treasure/book.json"),
57|      import("../data/books/treasure/analysis.json"),
58|    ),
59|};
60|
61|export function isKnownBookId(id: unknown): id is string {
62|  return typeof id === "string" && Object.hasOwn(LOADERS, id);
63|}
64|
65|const readyIds = new Set(library.map((entry) => entry.id));
66|
67|// Known plus listed on the shelf with status ready. The shelf manifest
68|// is the owner's switch: data alone does not publish a book.
69|export function isReadyBookId(id: unknown): boolean {
70|  return isKnownBookId(id) && readyIds.has(id);
71|}
72|
73|export function readyBookIds(): string[] {
74|  return library.map((entry) => entry.id).filter(isKnownBookId);
75|}
76|
77|// Parsed once per book per process; import failures are deterministic
78|// (a missing chunk never heals), so failed loads stay failed.
79|const cache = new Map<string, Promise<BookPayload>>();
80|
81|function readPayload(id: string): Promise<BookPayload> {
82|  const hit = cache.get(id);
83|  if (hit) return hit;
84|  const load = LOADERS[id];
85|  if (!load) notFound();
86|  const pending = load();
87|  cache.set(id, pending);
88|  return pending;
89|}
90|
91|// Processed data for any known id. Chat uses this: a question about a
92|// processed book is answerable whether the shelf lists it or not.
93|// Unknown ids throw notFound() synchronously, before any work starts.
94|export function loadBookData(bookId: string): Promise<BookPayload> {
95|  if (!isKnownBookId(bookId)) notFound();
96|  return readPayload(bookId);
97|}
98|
99|// Shelf books only. Unknown, unlisted, or traversal-ish ids 404.
100|export function loadBook(bookId: string): Promise<BookPayload> {
101|  if (!isReadyBookId(bookId)) notFound();
102|  return readPayload(bookId);
103|}

