1|import "server-only";
2|import type { AnalyzedScene, Chapter, KV, Paragraph } from "@/core/types";
3|import { UPLOAD_TTL_DAYS, isUploadId, uploadAnalysisPath, uploadBookPath } from "@/core/uploads";
4|import { createRestKV } from "@/server/guard/kv";
5|import { createUploadStore, type UploadStore } from "./blob";
6|import { readUploadEnv } from "./env";
7|import { loadUploadJob } from "./state";
8|
9|// The same shape the reader consumes for shelf books. The owner wires
10|// this into the generic book loader once that route lands.
11|export interface BookPayload {
12|  book: {
13|    id: string;
14|    title: string;
15|    author: string;
16|    chapters: Chapter[];
17|    paragraphs: Paragraph[];
18|    textVersion: string;
19|  };
20|  scenes: AnalyzedScene[];
21|}
22|
23|// Null when the id is bad, the job never finished, the book expired, or
24|// the stored data fails its shape check. Never throws.
25|export async function loadUploadedBook(
26|  id: string,
27|  deps: { kv?: KV; store?: UploadStore } = {},
28|): Promise<BookPayload | null> {
29|  if (!isUploadId(id)) return null;
30|  let kv = deps.kv;
31|  let store = deps.store;
32|  if (!kv || !store) {
33|    let env;
34|    try {
35|      env = readUploadEnv();
36|    } catch {
37|      return null;
38|    }
39|    kv ??= createRestKV(env.upstashUrl, env.upstashToken);
40|    store ??= createUploadStore(env.uploadsToken);
41|  }
42|  let job;
43|  try {
44|    job = await loadUploadJob(kv, id);
45|  } catch {
46|    return null;
47|  }
48|  if (!job || job.status !== "done") return null;
49|  if (Date.now() - job.createdAt > UPLOAD_TTL_DAYS * 24 * 3600 * 1000) return null;
50|  let bookRaw: string | null;
51|  let analysisRaw: string | null;
52|  try {
53|    [bookRaw, analysisRaw] = await Promise.all([
54|      store.readText(uploadBookPath(id)),
55|      store.readText(uploadAnalysisPath(id)),
56|    ]);
57|  } catch {
58|    return null;
59|  }
60|  if (bookRaw === null || analysisRaw === null) return null;
61|  let book: unknown;
62|  let analysis: unknown;
63|  try {
64|    book = JSON.parse(bookRaw);
65|    analysis = JSON.parse(analysisRaw);
66|  } catch {
67|    return null;
68|  }
69|  if (typeof book !== "object" || book === null || typeof analysis !== "object" || analysis === null) {
70|    return null;
71|  }
72|  const b = book as Partial<BookPayload["book"]>;
73|  const a = analysis as { bookId?: unknown; textVersion?: unknown; scenes?: unknown };
74|  if (b.id !== id || b.textVersion !== job.textVersion || a.bookId !== id || a.textVersion !== job.textVersion) {
75|    return null;
76|  }
77|  if (!Array.isArray(b.chapters) || !Array.isArray(b.paragraphs) || !Array.isArray(a.scenes)) return null;
78|  if (typeof b.title !== "string" || typeof b.author !== "string") return null;
79|  if (!a.scenes.every((s) => typeof s === "object" && s !== null && typeof (s as { id?: unknown }).id === "string")) {
80|    return null;
81|  }
82|  return { book: book as BookPayload["book"], scenes: a.scenes as AnalyzedScene[] };
83|}

