226|// Long chapters split into paragraph windows so one step stays in budget.
227|export function splitChapterParts(
228|  chapters: { ch: number; start_n: number; end_n: number }[],
229|  maxParas: number = UPLOAD_MAX_PART_PARAGRAPHS,
230|): UploadPart[] {
231|  const parts: UploadPart[] = [];
232|  for (const chapter of chapters) {
233|    let part = 1;
234|    for (let start = chapter.start_n; start <= chapter.end_n; start += maxParas, part += 1) {
235|      parts.push({ ch: chapter.ch, part, startN: start, endN: Math.min(start + maxParas - 1, chapter.end_n) });
236|    }
237|  }
238|  return parts;
239|}
