91|async function ensureAnon(cookieHeader: string | null, secret: string, cookies: string[]): Promise<string> {
92|  const found = verifyAnonCookie(parseAnonCookie(cookieHeader), secret);
93|  if (found) return found;
94|  const issued = issueAnonId(secret);
95|  cookies.push(serializeAnonCookie(issued.value));
96|  return issued.id;
97|}
98|
99|// Order: same-origin, body cap, strict parse, env, Turnstile, anon cookie,
100|// BYOK header, then quota/spend inside create (free only). User errors
101|// never take quota; server failures refund.
102|export async function handleUploadsCreate(req: Request, deps: UploadHandlerDeps = {}): Promise<Response> {
103|  const cookies: string[] = [];
104|  if (rejectsCrossSite(req.headers, req.url)) return fail("bad_request", cookies);
105|  const capped = await readBodyCapped(req, UPLOAD_MAX_BODY_BYTES);
106|  if (!capped.ok) return fail("bad_request", cookies);
107|  let body: UploadCreateBody;
108|  try {
109|    body = parseUploadCreate(JSON.parse(capped.text));
110|  } catch {
111|    return fail("bad_request", cookies);
112|  }
113|  let env = deps.env;
114|  if (!env) {
115|    try {
116|      env = readUploadEnv();
117|    } catch {
118|      // fail() logs the one warning; missing names stay out of the log.
119|      return fail("unavailable", cookies);
120|    }
121|  }
122|  const fetchFn = deps.fetchFn ?? fetch;
123|  const ip = clientIp(req.headers);
124|  const human = await checkHuman({
125|    cookieHeader: req.headers.get("cookie"),
126|    token: body.turnstileToken,
127|    ip,
128|    turnstileSecret: env.turnstileSecret,
129|    turnstileSiteKey: env.turnstileSiteKey,
130|    sessionSecret: env.sessionSecret,
131|    fetchFn,
132|  });
133|  if (!human.ok) return fail("human_required", cookies);
134|  if (human.setCookie) cookies.push(human.setCookie);
135|  const anonId = await ensureAnon(req.headers.get("cookie"), env.sessionSecret, cookies);
136|  const byokKey = parseByokHeader(req.headers.get(BYOK_HEADER));
137|  if (byokKey === false) return fail("bad_request", cookies);
138|  const meta = buildMeta(deps, fetchFn, byokKey ?? env.metaKey);
139|  if (!meta) return fail("unavailable", cookies);
140|  const kv = deps.kv ?? createRestKV(env.upstashUrl, env.upstashToken);
141|  const day = utcDay(deps.now ?? new Date());
142|  try {
143|    const out = await createUpload({
144|      kv,
145|      store: deps.store ?? createUploadStore(env.uploadsToken),
146|      meta,
147|      body,
148|      path: byokKey ? "byok" : "free",
149|      anonId,
150|      day,
151|      quotaKeys: byokKey ? null : bookQuotaKeysFor({ day, ip, salt: env.ipSalt, anonId }),
152|      spendCapMicro: env.spendCapMicro,
153|    });
154|    return Response.json(
155|      { status: "created", id: out.id, chapters: out.chapters, parts: out.parts },
156|      { status: 200, headers: withCookies(cookies) },
157|    );
158|  } catch (e) {
159|    if (e instanceof UploadFailure) return fail(e.code, cookies, e.code === "unavailable");
160|    return fail("unavailable", cookies, true);
161|  }
162|}
163|
164|// Free jobs bind the anon cookie, so another browser cannot drive them;
165|// BYOK jobs need the key header on every call and never touch our Jev key.
166|export async function handleUploadStep(req: Request, id: string, deps: UploadHandlerDeps = {}): Promise<Response> {
167|  const cookies: string[] = [];
168|  if (!isUploadId(id)) return fail("not_found", cookies);
169|  if (rejectsCrossSite(req.headers, req.url)) return fail("bad_request", cookies);
170|  const capped = await readBodyCapped(req, UPLOAD_STEP_BODY_BYTES);
171|  if (!capped.ok) return fail("bad_request", cookies);
172|  let chapter: number | undefined;
173|  let token: string | undefined;
174|  try {
175|    ({ chapter, turnstileToken: token } = parseStepBody(capped.text === "" ? {} : JSON.parse(capped.text)));
176|  } catch {
177|    return fail("bad_request", cookies);
178|  }
179|  let env = deps.env;
180|  if (!env) {
181|    try {
182|      env = readUploadEnv();
183|    } catch {
184|      // fail() logs the one warning; missing names stay out of the log.
185|      return fail("unavailable", cookies);
186|    }
187|  }
188|  const fetchFn = deps.fetchFn ?? fetch;
189|  const ip = clientIp(req.headers);
190|  const human = await checkHuman({
191|    cookieHeader: req.headers.get("cookie"),
192|    token,
193|    ip,
194|    turnstileSecret: env.turnstileSecret,
195|    turnstileSiteKey: env.turnstileSiteKey,
196|    sessionSecret: env.sessionSecret,
197|    fetchFn,
198|  });
199|  if (!human.ok) return fail("human_required", cookies);
200|  if (human.setCookie) cookies.push(human.setCookie);
201|  const anonId = await ensureAnon(req.headers.get("cookie"), env.sessionSecret, cookies);
202|  const byokKey = parseByokHeader(req.headers.get(BYOK_HEADER));
203|  if (byokKey === false) return fail("bad_request", cookies);
204|  const kv = deps.kv ?? createRestKV(env.upstashUrl, env.upstashToken);
205|  let job;
206|  try {
207|    job = await loadUploadJob(kv, id);
208|  } catch {
209|    return fail("unavailable", cookies, true);
210|  }
211|  if (!job) return fail("not_found", cookies);
212|  if (job.path === "free") {
213|    if (job.anonId === null || anonId !== job.anonId) return fail("not_found", cookies);
214|  } else if (!byokKey) {
215|    return fail("bad_request", cookies);
216|  }
217|  const byok = job.path === "byok";
218|  const meta = buildMeta(deps, fetchFn, byok ? (byokKey as string) : env.metaKey);
219|  if (!meta) return fail("unavailable", cookies);
220|  try {
221|    const out = await stepUpload({
222|      kv,
223|      store: deps.store ?? createUploadStore(env.uploadsToken),
224|      meta,
225|      jev: buildJev(deps, fetchFn, env, byok),
226|      id,
227|      ...(chapter === undefined ? {} : { chapter }),
228|    });
229|    return Response.json(out, { status: 200, headers: withCookies(cookies) });
230|  } catch (e) {
231|    if (e instanceof UploadFailure) return fail(e.code, cookies, e.code === "unavailable");
232|    return fail("unavailable", cookies, true);
233|  }
