263|// Private Blob layout; the id is unguessable, URLs never leave the server.
264|export function uploadBookPath(id: string): string {
265|  return `uploads/${id}/book.json`;
266|}
267|
268|export function uploadPartPath(id: string, part: string): string {
269|  return `uploads/${id}/part-${part}.json`;
270|}
271|
272|export function uploadAnalysisPath(id: string): string {
273|  return `uploads/${id}/analysis.json`;
274|}
275|
276|export function uploadDailySpendKey(day: string): string {
277|  return `upload:spend:daily:${day}`;
