48|// Codes only, never internals or keys. Server failures error, the rest warn.
49|function fail(code: UploadErrorCode, cookies: string[], unexpected = false): Response {
50|  if (unexpected) console.error(`upload ${code}`);
51|  else console.warn(`upload ${code}`);
52|  const headers = new Headers();
53|  for (const cookie of cookies) headers.append("Set-Cookie", cookie);
