88|// client bug cannot widen the context or spend budget on a misread request.
89|export function parseChatRequest(json: unknown): ChatRequest {
90|  if (!isRecord(json)) throw new ChatValidationError();
91|  // Shape only here; the handler checks the id against the book registry.
92|  const bookId = json.bookId;
93|  if (typeof bookId !== "string" || bookId.length === 0 || bookId.length > 64) {
94|    throw new ChatValidationError();
95|  }
96|  const upToN = json.upToN;
97|  if (typeof upToN !== "number" || !Number.isSafeInteger(upToN) || upToN <= 0) {
98|    throw new ChatValidationError();
99|  }
100|  if (typeof json.spoilers !== "boolean") throw new ChatValidationError();
101|  const rawMessages = json.messages;
102|  if (!Array.isArray(rawMessages) || rawMessages.length < 1 || rawMessages.length > CHAT_MAX_MESSAGES + 1) {
