104|  }
105|  const messages: ChatMessage[] = rawMessages.map((item, index) => {
106|    if (!isRecord(item)) throw new ChatValidationError();
107|    if (item.role !== "user" && item.role !== "assistant") throw new ChatValidationError();
108|    if (typeof item.content !== "string" || item.content.length === 0) {
109|      throw new ChatValidationError();
110|    }
111|    const last = index === rawMessages.length - 1;
112|    if (item.role === "user") {
