77|// One read with an idle budget. Handlers stay attached, so a won read
78|// settling late after the timeout never rejects unhandled.
79|function readWithIdle(
80|  reader: ReadableStreamDefaultReader<Uint8Array>,
81|  ms: number,
82|): Promise<ReadableStreamReadResult<Uint8Array>> {
83|  return new Promise((resolve, reject) => {
84|    const timer = setTimeout(() => reject(IDLE_TIMEOUT), ms);
85|    reader.read().then(
86|      (value) => {
87|        clearTimeout(timer);
88|        resolve(value);
89|      },
