98|// Minimal SSE reader: splits on blank lines, reads event:/data: pairs.
99|// Each read gets the idle budget; a stall throws the retryable code.
100|export async function runStream(
101|  res: Response,
102|  signal: AbortSignal,
103|  onBlock: (event: string, data: string) => void,
104|  idleMs: number = CHAT_IDLE_MS,
105|): Promise<void> {
106|  const reader = res.body?.getReader();
107|  if (!reader) throw { code: "unavailable" };
108|  const decoder = new TextDecoder();
109|  let buf = "";
110|  for (;;) {
111|    let read: ReadableStreamReadResult<Uint8Array>;
112|    try {
113|      read = await readWithIdle(reader, idleMs);
114|    } catch (err) {
115|      if (err === IDLE_TIMEOUT) {
116|        try {
117|          await reader.cancel();
118|        } catch {
119|          // Already closed; the timeout itself is the outcome.
120|        }
121|        throw { code: "unavailable" };
122|      }
123|      throw err;
124|    }
125|    const { done, value } = read;
126|    if (signal.aborted) {
127|      try {
128|        await reader.cancel();
129|      } catch {
130|        // Already closed; the abort itself is the outcome.
131|      }
132|      return;
133|    }
134|    buf += decoder.decode(value ?? new Uint8Array(), { stream: !done });
135|    let idx: number;
136|    while ((idx = buf.indexOf("\n\n")) >= 0) {
137|      const block = buf.slice(0, idx);
138|      buf = buf.slice(idx + 2);
139|      let event = "";
140|      const lines: string[] = [];
141|      for (const line of block.split("\n")) {
142|        if (line.startsWith("event:")) event = line.slice(6).trim();
143|        else if (line.startsWith("data:")) lines.push(line.slice(5).trimStart());
144|      }
145|      onBlock(event, lines.join("\n"));
146|    }
147|    if (done) break;
148|  }
