155|// Book text the reader has reached, grouped under one line per chapter so
156|// the shape is stable and shared across readers at the same position.
157|export function bookTextUpTo(
158|  paragraphs: ChatBookContext["paragraphs"],
159|  chapters: ChatBookContext["chapters"],
160|  upToN: number,
161|  spoilers: boolean,
162|): string {
163|  const maxN = paragraphs.reduce((m, p) => Math.max(m, p.n), 0);
164|  const limit = spoilers ? maxN : Math.min(upToN, maxN);
165|  const titles = new Map(chapters.map((c) => [c.ch, c.title]));
166|  const kept = paragraphs
167|    .filter((p) => p.n <= limit)
168|    .sort((a, b) => a.n - b.n);
169|  const groups = new Map<number, string[]>();
170|  for (const p of kept) {
171|    const list = groups.get(p.ch) ?? [];
172|    list.push(p.text);
173|    groups.set(p.ch, list);
174|  }
175|  return [...groups.entries()]
176|    .sort((a, b) => a[0] - b[0])
177|    .map(([ch, texts]) => `Chapter ${ch}: ${titles.get(ch) ?? "Untitled"}\n\n${texts.join("\n\n")}`)
178|    .join("\n\n");
