207|// Reserve math in integer micro-dollars: input $1.25/M, cached input
208|// $0.15/M, output $4.25/M. The 2x on max tokens covers low reasoning.
209|export function estimateCostMicro(promptChars: number): number {
210|  return Math.ceil((promptChars / 4) * 1.25) + Math.ceil(CHAT_MAX_TOKENS * 2 * 4.25);
