397|        <a href="#story" className="skip-link">
398|          Skip to the story
399|        </a>
400|        <TopLine
401|          bookTitle={bookTitle}
402|          author={bookAuthor}
403|          ch={routeSceneId ? (scenes[bookIndex]?.ch ?? chapters[0]?.ch ?? 1) : 1}
404|          chaptersTotal={chapters.length}
405|          chapters={chapters}
406|          onJumpChapter={jumpChapter}
407|          theme={theme}
408|          onToggleTheme={toggleTheme}
409|        />
410|        {children}
411|        <BandPlay
412|          narrationOn={narration.length > 0}
413|          musicFailed={musicFailed}
414|          empty={empty}
415|          track={track}
416|          replayNonce={view?.replayNonce ?? 0}
417|          fadeSec={view?.fadeSec ?? 0}
418|          canPrev={canPrev}
419|          onPrev={goPrev}
420|          canSkip={canSkip}
421|          onSkip={skip}
422|          volume={volume}
423|          muted={muted}
424|          onVolumeChange={changeVolume}
425|          onMutedChange={changeMuted}
426|          modes={modes}
427|          current={modeCurrent}
428|          onAdvance={advanceMode}
429|          onEnded={ended}
430|          playlistOn={playlistOn}
431|        />
432|      {chatScene && chatChapter && (
433|        <ReaderChat
434|          bookId={bookId}
435|          upToN={chatScene.endN}
436|          chapter={chatChapter.ch}
437|          chapterTitle={chatChapter.title}
438|        />
439|      )}
440|      <DevPanel
441|        open={devOpen}
442|        onClose={() => setDevOpen(false)}
443|        sceneLabel={bookIndex >= 0 ? `scene ${bookIndex + 1} of ${scenes.length}` : "no scene"}
444|        bars={devBars}
445|        intensity={current?.intensity ?? null}
446|        tempo={current?.tempo ?? null}
447|        trackTitle={track?.title ?? "No track cued"}
448|        sceneAttr={sceneAttr}
449|      />
450|      </div>
451|    </NarrationProvider>
452|  );
453|}
