151|  const [view, setView] = useState<SessionView | null>(null);
152|  const [musicFailed, setMusicFailed] = useState(false);
153|  // Volume, mute, style, and Chopin mode persist in one prefs object;
154|  // the player stays a controlled view over them. State starts at the server
155|  // defaults so hydration matches, then a mount effect applies stored
156|  // prefs (parsed once) to volume, muted, and style via the prefs store.
157|  const [volume, setVolume] = useState(DEFAULT_VOLUME);
158|  const [muted, setMuted] = useState(false);
159|  const [theme, setTheme] = useState<"light" | "dark">("light");
160|  const [devOpen, setDevOpen] = useState(false);
161|  const [sceneAttr, setSceneAttr] = useState<SceneAttr | null>(null);
162|  const prefsStoreRef = useRef(createMusicPrefsStore());
163|  // Ref mirrors so send and persist handlers always read fresh values.
164|  const volumeRef = useRef(volume);
165|  volumeRef.current = volume;
166|  const mutedRef = useRef(muted);
167|  mutedRef.current = muted;
168|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
169|  const byIdRef = useRef(byId);
170|  byIdRef.current = byId;
171|  const manifestRef = useRef(manifest);
172|  manifestRef.current = manifest;
173|  const routeRef = useRef(routeSceneId);
174|  routeRef.current = routeSceneId;
175|  const sessionRef = useRef<MusicSession | null>(null);
176|  const observedRef = useRef<string | null>(null);
177|
178|  // The one bridge into the session: builds the context (clock, rng,
179|  // scene signals) and mirrors the view and a style change to state.
180|  const send = useCallback((intent: MusicIntent) => {
181|    const session = sessionRef.current;
182|    const fetched = manifestRef.current;
183|    if (!session || !fetched) return;
184|    const prevView = session.view;
185|    const next = dispatch(session, intent, {
186|      manifest: fetched,
187|      signalOf: (sceneId) => byIdRef.current.get(sceneId) ?? null,
188|      routeSceneId: routeRef.current,
189|      nowSec: Date.now() / 1000,
190|      rng: Math.random,
191|      excludeTrackId: prefsStoreRef.current.load()?.lastTrackId ?? null,
192|    });
193|    sessionRef.current = next;
194|    if (next.view !== prevView) setView(next.view);
195|    // Remember the last track that started playing so the next session
196|    // opens on something else. Merge-updates never clobber other fields.
197|    if (next.view.currentId !== prevView.currentId && next.view.currentId !== null) {
198|      prefsStoreRef.current.update({ lastTrackId: next.view.currentId });
199|    }
200|    if (next.selection !== session.selection || next.view.playlistOn !== prevView.playlistOn) {
201|      prefsStoreRef.current.update({
202|        style: next.selection.style,
203|        playlist: next.view.playlistOn,
204|      });
205|    }
206|  }, []);
207|
208|  // Stored prefs load once here, after the server-matching first render.
209|  // Saves happen only on user actions below, so the defaults above never
210|  // overwrite storage before this runs. The fetch below resolves later and
211|  // reads the style through the store.
212|  useEffect(() => {
213|    const prefs = prefsStoreRef.current.load();
214|    if (prefs !== null) {
215|      if (prefs.volume !== null) setVolume(prefs.volume);
216|      setMuted(prefs.muted);
217|    }
218|    try {
219|      setTheme(initialTheme(window.localStorage.getItem(THEME_KEY)));
220|    } catch {
221|      // The inline script already set a theme; keep the default.
222|    }
223|    if (new URLSearchParams(window.location.search).has("dev")) setDevOpen(true);
224|  }, []);
225|
226|  useEffect(() => {
227|    let cancelled = false;
228|    fetch("/music/manifest.json", { signal: AbortSignal.timeout(15_000) })
229|      .then((res) => {
230|        if (!res.ok) throw new Error(`manifest ${res.status}`);
231|        return res.json();
232|      })
233|      .then((json: unknown) => {
234|        if (cancelled) return;
235|        const parsed = choosePlayableSources(parseManifest(json), canPlayAudio);
236|        setManifest(parsed);
237|        const session = startSession(parsed, prefsStoreRef.current.load(), Math.random);
238|        sessionRef.current = session;
239|        setView(session.view);
240|      })
241|      .catch(() => {
242|        if (!cancelled) setMusicFailed(true);
243|      });
244|    return () => {
245|      cancelled = true;
246|    };
247|  }, []);
248|
249|  // Scene entry: exactly one sceneEntered per scene id, once the manifest
250|  // lands. The first scene cues at once, so it plays on the first press.
251|  useEffect(() => {
252|    const gate = nextSceneEntry({
253|      observedId: observedRef.current,
254|      routeId: routeSceneId,
255|      manifestReady: manifest !== null,
256|    });
257|    observedRef.current = gate.nextObservedId;
258|    if (gate.shouldObserve && routeSceneId) send({ type: "sceneEntered", sceneId: routeSceneId });
259|  }, [routeSceneId, manifest, send]);
260|
261|  useEffect(() => {
262|    // Settle an expired entry dwell, or re-check the scene after a hold.
263|    const timer = window.setInterval(() => {
264|      send({ type: "tick" });
265|    }, 1000);
266|    return () => window.clearInterval(timer);
267|  }, [send]);
268|
269|  // Developer view slice: fetched on demand while the panel is open,
270|  // so the page never ships all scenes' attrs. Stale requests abort on
271|  // scene change; any failure hides the section.
272|  useEffect(() => {
273|    if (!devOpen || !routeSceneId) {
274|      setSceneAttr(null);
275|      return;
276|    }
277|    const controller = new AbortController();
278|    setSceneAttr(null);
279|    fetch(
280|      `/api/scene-attrs?bookId=${encodeURIComponent(bookId)}&sceneId=${encodeURIComponent(routeSceneId)}`,
281|      { signal: controller.signal },
282|    )
283|      .then((res) => {
284|        if (!res.ok) throw new Error(`scene attrs ${res.status}`);
285|        return res.json() as Promise<unknown>;
286|      })
287|      .then((json) => {
288|        if (isSceneAttr(json)) setSceneAttr(json);
289|      })
290|      .catch(() => {
291|        // The panel hides the section on any failure.
292|      });
293|    return () => controller.abort();
294|  }, [devOpen, routeSceneId, bookId]);
295|
296|  // Developer view: Shift+D outside inputs, Escape closes.
297|  useEffect(() => {
298|    const onKey = (event: KeyboardEvent) => {
299|      const target = event.target as HTMLElement | null;
300|      const typing =
301|        !!target &&
302|        (target.tagName === "INPUT" ||
303|          target.tagName === "SELECT" ||
304|          target.tagName === "TEXTAREA" ||
305|          target.isContentEditable);
306|      if (event.key === "Escape") {
307|        setDevOpen(false);
308|        return;
309|      }
310|      if (typing) return;
311|      if (event.shiftKey && (event.key === "D" || event.key === "d")) {
312|        event.preventDefault();
313|        setDevOpen((open) => !open);
314|      }
315|    };
316|    window.addEventListener("keydown", onKey);
317|    return () => window.removeEventListener("keydown", onKey);
318|  }, []);
319|
320|  function skip() {
321|    send({ type: "skip" });
322|  }
323|
324|  // Previous: back to the last played track, held like a Next. With no
325|  // history the current track restarts from zero through the replay path,
326|  // including in playlist mode.
327|  function goPrev() {
328|    send({ type: "previous" });
329|  }
330|
331|  function advanceMode(to?: MusicModeId) {
332|    send({ type: "modeAdvanced", to });
333|  }
334|
335|  function changeVolume(next: number) {
336|    setVolume(next);
337|    volumeRef.current = next;
338|    prefsStoreRef.current.update({ volume: next });
339|  }
340|
341|  function changeMuted(next: boolean) {
342|    setMuted(next);
343|    mutedRef.current = next;
344|    prefsStoreRef.current.update({ muted: next });
345|  }
346|
347|  function ended(trackId: string) {
348|    send({ type: "trackEnded", trackId });
349|  }
350|
351|  function toggleTheme() {
352|    setTheme((current) => {
353|      const next = current === "dark" ? "light" : "dark";
354|      document.documentElement.setAttribute("data-theme", next);
355|      try {
356|        window.localStorage.setItem(THEME_KEY, next);
357|      } catch {
358|        // The attribute already applies for the session.
359|      }
360|      return next;
361|    });
362|  }
363|
364|  function jumpChapter(ch: number) {
365|    const found = chapters.find((c) => c.ch === ch);
366|    if (found) requestGotoScene(found.firstSceneId);
367|  }
368|
369|  const currentId = view?.currentId ?? null;
370|  const track = manifest?.tracks.find((t) => t.id === currentId) ?? null;
371|  const empty = manifest !== null && manifest.tracks.length === 0;
372|  // Ordered music modes for the control: styles with tracks, then Chopin.
373|  const modes = manifest ? musicModes(manifest) : [];
374|  const modeCurrent = view ? currentMode(view) : null;
375|  const playlistOn = view?.playlistOn ?? false;
376|  // Previous restarts the track with no history (including the current
377|  // playlist piece), so it stays on whenever a track is cued.
378|  const canPrev = view?.canPrev ?? false;
379|  const canSkip = view?.canSkip ?? false;
380|
381|  const bookIndex = routeSceneId ? scenes.findIndex((s) => s.id === routeSceneId) : -1;
382|  const current = routeSceneId ? byId.get(routeSceneId) ?? null : null;
383|  // Reader chat position: the scene in view, or the first scene on load.
384|  const chatScene = (routeSceneId ? scenes.find((s) => s.id === routeSceneId) : null) ?? scenes[0];
385|  const chatChapter = chapters.find((c) => c.ch === chatScene?.ch) ?? chapters[0];
386|  const devBars = current
387|    ? EMOTIONS.map((id) => ({ label: DEV_LABELS[id], value: current.vector[id] ?? 0 }))
388|    : [];
389|
390|
391|  // Pictures, panels, and narration are Oz-only; music follows any
392|  // book's scene emotions, so it stays on everywhere.
393|  const picturesOn = bookId === "oz";
394|  return (
395|    <NarrationProvider entries={narration} scenes={scenes}>
396|      <div className="folio" data-pictures={picturesOn ? "on" : "off"}>
397|        <a href="#story" className="skip-link">
398|          Skip to the story
399|        </a>
400|        <TopLine
401|          bookTitle={bookTitle}
402|          author={bookAuthor}
403|          ch={routeSceneId ? (scenes[bookIndex]?.ch ?? chapters[0]?.ch ?? 1) : 1}
404|          chaptersTotal={chapters.length}
405|          chapters={chapters}
406|          onJumpChapter={jumpChapter}
407|          theme={theme}
408|          onToggleTheme={toggleTheme}
409|        />
410|        {children}
411|        <BandPlay
412|          narrationOn={narration.length > 0}
413|          musicFailed={musicFailed}
414|          empty={empty}
415|          track={track}
416|          replayNonce={view?.replayNonce ?? 0}
417|          fadeSec={view?.fadeSec ?? 0}
418|          canPrev={canPrev}
419|          onPrev={goPrev}
420|          canSkip={canSkip}
421|          onSkip={skip}
422|          volume={volume}
423|          muted={muted}
424|          onVolumeChange={changeVolume}
425|          onMutedChange={changeMuted}
426|          modes={modes}
427|          current={modeCurrent}
428|          onAdvance={advanceMode}
429|          onEnded={ended}
430|          playlistOn={playlistOn}
431|        />
432|      {chatScene && chatChapter && (
433|        <ReaderChat
434|          bookId={bookId}
435|          upToN={chatScene.endN}
436|          chapter={chatChapter.ch}
437|          chapterTitle={chatChapter.title}
438|        />
439|      )}
440|      <DevPanel
441|        open={devOpen}
442|        onClose={() => setDevOpen(false)}
443|        sceneLabel={bookIndex >= 0 ? `scene ${bookIndex + 1} of ${scenes.length}` : "no scene"}
444|        bars={devBars}
445|        intensity={current?.intensity ?? null}
446|        tempo={current?.tempo ?? null}
447|        trackTitle={track?.title ?? "No track cued"}
448|        sceneAttr={sceneAttr}
449|      />
450|      </div>
451|    </NarrationProvider>
452|  );
