2|import { sceneAttributes } from "@/core/bookmap";
3|import { loadBookmap } from "@/server/bookmap";
4|import { isReadyBookId, loadBookData } from "@/server/books";
5|
6|// Scene ids look like c1s1 or c1s1b: chapter, scene, optional split suffix.
7|const SCENE_ID_RE = /^c\d+s\d+[a-z]?$/;
8|
9|function notFound(): Response {
10|  return Response.json({ error: "not found" }, { status: 404 });
11|}
12|
13|// One scene's Developer View slice: setting, cast names, key objects.
14|// The page never ships it; the panel fetches it while open. Static per
15|// deploy, so the response caches publicly. No Redis, no Meta, no secrets.
16|export async function handleSceneAttrsGet(req: Request): Promise<Response> {
17|  try {
18|    const params = new URL(req.url).searchParams;
19|    const bookId = params.get("bookId") ?? "";
20|    const sceneId = params.get("sceneId") ?? "";
21|    if (!isReadyBookId(bookId) || !SCENE_ID_RE.test(sceneId)) return notFound();
22|    const { book, scenes } = await loadBookData(bookId);
23|    const scene = scenes.find((s) => s.id === sceneId);
24|    if (!scene) return notFound();
25|    const attr = sceneAttributes(loadBookmap(book.id, book.textVersion), [
26|      { id: sceneId, ch: scene.ch },
27|    ])[sceneId];
28|    if (!attr) return notFound();
29|    return Response.json(attr, { headers: { "Cache-Control": "public, max-age=86400" } });
30|  } catch {
31|    console.error("scene-attrs failed");
32|    return Response.json({ error: "unavailable" }, { status: 500 });
33|  }
