1|import "server-only";
2|import { readFileSync } from "node:fs";
3|import { join } from "node:path";
4|import type { NarrationChapterEntry } from "../app/narration/types";
5|
6|// Small chapter map for the reader shell: each chapter's audio src and
7|// its manifest URL (src with .mp3 replaced by .json). The 1 MB Oz index
8|// never reaches the client; only this list of chapters ships. Prebuilt
9|// narration exists for Oz only; other books read silently.
10|export function loadNarrationEntries(bookId: string): NarrationChapterEntry[] {
11|  if (bookId !== "oz") return [];
12|  const raw = readFileSync(join(process.cwd(), "data/books/oz/narration.json"), "utf8");
13|  const json = JSON.parse(raw) as { chapters?: Record<string, { src?: string }> };
14|  const chapters = json.chapters ?? {};
15|  return Object.keys(chapters)
16|    .map(Number)
17|    .filter((ch) => Number.isInteger(ch))
18|    .sort((a, b) => a - b)
19|    .flatMap((ch) => {
20|      const src = chapters[String(ch)]?.src;
21|      if (typeof src !== "string" || !src.endsWith(".mp3")) return [];
22|      return [{ ch, src, manifest: src.slice(0, -4) + ".json" }];
23|    });
24|}

