1|"use client";
2|
3|import { useRef, useState } from "react";
4|import { ChatPanel } from "./chat-panel";
5|import { CHAT_COPY, CHAT_LABEL } from "./copy";
6|import { SUGGESTED_QUESTIONS } from "./suggestions";
7|import { useChat } from "./use-chat";
8|import { ChatBubble } from "./chat-bubble";
9|
10|// Launcher + panel shell. Mounted once inside the reader folio; the key it
11|// holds lives in state only, so reload and panel close clear it.
12|export function ReaderChat({
13|  bookId,
14|  upToN,
15|  chapter,
16|  chapterTitle,
17|}: {
18|  bookId: string;
19|  upToN: number;
20|  chapter: number;
21|  chapterTitle: string;
22|}) {
23|  const [open, setOpen] = useState(false);
24|  const [byokKey, setByokKey] = useState<string | null>(null);
25|  const [turnstileToken, setTurnstileToken] = useState<string | null>(null);
26|  const launcherRef = useRef<HTMLButtonElement | null>(null);
27|
28|  const chat = useChat({
29|    bookId,
30|    upToN,
31|    byokKey,
32|    turnstileToken,
33|    onTokenUsed: () => setTurnstileToken(null),
34|  });
35|
36|  function close() {
37|    setOpen(false);
38|    setByokKey(null); // Memory only: closing forgets the key.
39|    launcherRef.current?.focus();
40|  }
41|
42|  return (
43|    <div className="reader-chat">
44|      {open && (
45|        <ChatPanel
46|          chapter={chapter}
47|          chapterTitle={chapterTitle}
48|          chat={chat}
49|          suggestions={[...SUGGESTED_QUESTIONS]}
50|          byokKey={byokKey}
51|          onKeySubmit={(key) => {
52|            setByokKey(key);
53|            chat.retry({ key });
54|          }}
55|          onHumanPass={(token) => {
56|            chat.setNeedHuman(false);
57|            setTurnstileToken(token);
58|            chat.retry({ token });
59|          }}
60|          onClose={close}
61|        />
62|      )}
63|      <button
64|        ref={launcherRef}
65|        type="button"
66|        className="chat-launch"
67|        aria-expanded={open}
68|        aria-controls="chat-panel"
69|        aria-label={open ? CHAT_COPY.closeChat : undefined}
70|        onClick={() => (open ? close() : setOpen(true))}
71|      >
72|        <span className="chat-launch-label">{open ? CHAT_COPY.close : CHAT_LABEL}</span>
73|        <ChatBubble open={open} />
74|      </button>
75|    </div>
76|  );
77|}

