1|// Chapter panels: one comic page per chapter, captions below it in
2|// reading order. The page generates on demand in the reader's style;
3|// chapters past the reader's reach stay gated.
4|"use client";
5|
6|import { useEffect, useRef } from "react";
7|import { TurnstileWidget } from "../turnstile";
8|import type { ImageStylePref } from "../image-style";
9|import type { ChapterPanel } from "./panels";
10|import { PICTURE_COPY } from "./picture-copy";
11|import { PictureDraw, PictureWait } from "./picture-draw";
12|import { PANELS_NOTE } from "./picture-draw-paths";
13|import { usePictureSkin } from "./picture-skin";
14|import { useChapterPage } from "./use-chapter-page";
15|
16|export function PanelsModal({
17|  ch,
18|  chapterTitle,
19|  panels,
20|  bookId,
21|  textVersion,
22|  pref,
23|  reachedCh,
24|  onClose,
25|  onOpenArt,
26|}: {
27|  ch: number;
28|  chapterTitle: string;
29|  panels: ChapterPanel[];
30|  bookId: string;
31|  textVersion: string;
32|  pref: ImageStylePref;
33|  reachedCh: number;
34|  onClose: () => void;
35|  onOpenArt: (src: string, caption: string, opener: HTMLElement | null) => void;
36|}) {
37|  const chapterLabel = `Chapter ${ch}, ${chapterTitle}`;
38|  const reached = ch <= reachedCh;
39|  const skin = usePictureSkin();
40|  const { page, retry, needHuman, submitHumanPass } = useChapterPage({ bookId, textVersion, ch, pref, reachedCh });
41|  const closeRef = useRef<HTMLButtonElement | null>(null);
42|  const boxRef = useRef<HTMLDivElement | null>(null);
43|
44|  useEffect(() => {
45|    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
46|    closeRef.current?.focus();
47|    const onKey = (event: KeyboardEvent) => {
48|      if (event.key === "Escape") {
49|        // The shared lightbox sits above the modal and closes itself.
50|        if (document.querySelector(".lightbox")) return;
51|        event.stopPropagation();
52|        onClose();
53|        return;
54|      }
55|      if (event.key !== "Tab" || !boxRef.current) return;
56|      const items = [...boxRef.current.querySelectorAll<HTMLElement>("button, [href], [tabindex]:not([tabindex='-1'])")].filter(
57|        (el) => !el.hasAttribute("disabled"),
58|      );
59|      if (items.length === 0) return;
60|      const first = items[0] as HTMLElement;
61|      const last = items[items.length - 1] as HTMLElement;
62|      if (event.shiftKey && document.activeElement === first) {
63|        event.preventDefault();
64|        last.focus();
65|      } else if (!event.shiftKey && document.activeElement === last) {
66|        event.preventDefault();
67|        first.focus();
68|      }
69|    };
70|    document.addEventListener("keydown", onKey, true);
71|    return () => {
72|      document.removeEventListener("keydown", onKey, true);
73|      opener?.focus?.({ preventScroll: true });
74|    };
75|  }, [onClose]);
76|
77|  return (
78|    <div className="panels-modal" role="dialog" aria-modal="true" aria-label={chapterLabel}>
79|      <div ref={boxRef} className="panels-box">
80|        <button ref={closeRef} type="button" className="panels-x" onClick={onClose} aria-label="Close">
81|          ×
82|        </button>
83|        <p className="panels-head">
84|          Chapter {ch} · {chapterTitle}
85|        </p>
86|        {reached ? (
87|          <>
88|            {page.phase === "ready" ? (
89|              <button
90|                type="button"
91|                className="panels-frame"
92|                onClick={(e) => onOpenArt(page.url, chapterLabel, e.currentTarget)}
93|                aria-label={`Open art: ${chapterLabel}`}
94|              >
95|                <img src={page.url} alt="" />
96|              </button>
97|            ) : page.phase === "loading" ? (
98|              <div className="panels-frame">
99|                <PictureDraw skin={skin} />
100|              </div>
101|            ) : (
102|              <div className="panels-frame panels-miss" role="alert">
103|                <p>{page.message}</p>
104|                {needHuman ? (
105|                  <TurnstileWidget onToken={submitHumanPass} />
106|                ) : page.quota ? (
107|                  <p>{PICTURE_COPY.quotaByok}</p>
108|                ) : (
109|                  <button type="button" className="retry-text" onClick={retry}>
110|                    {PICTURE_COPY.retry}
111|                  </button>
112|                )}
113|              </div>
114|            )}
115|            {page.phase === "loading" ? <PictureWait skin={skin} note={PANELS_NOTE} /> : null}
116|            <ol className="panels-caps">
117|              {panels.map((p) => (
118|                <li key={p.key}>{p.caption}</li>
119|              ))}
120|            </ol>
121|          </>
122|        ) : (
123|          <p className="panels-gate">Read up to this chapter first.</p>
124|        )}
125|      </div>
126|    </div>
127|  );
