1|// @vitest-environment jsdom
2|// Shelf links: every ready book's plate reads /read/<id>, and books
3|// still off the shelf show the coming-soon plate instead. Driven by
4|// the shelf data, so enabling a book needs no test change.
5|import { act } from "react";
6|import { createRoot, type Root } from "react-dom/client";
7|import { afterEach, beforeEach, describe, expect, test } from "vitest";
8|import { shelf } from "./shelf";
9|import { HomeSpread } from "./spread";
10|
11|(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
12|
13|let container: HTMLDivElement;
14|let root: Root | null = null;
15|
16|function click(el: Element) {
17|  act(() => {
18|    el.dispatchEvent(new MouseEvent("click", { bubbles: true }));
19|  });
20|}
21|
22|function shelfButton(id: string): HTMLButtonElement {
23|  const el = container.querySelector(`.lb-item[data-book="${id}"]`);
24|  if (!(el instanceof HTMLButtonElement)) throw new Error(`shelf button missing: ${id}`);
25|  return el;
26|}
27|
28|beforeEach(() => {
29|  document.body.innerHTML = "";
30|  container = document.createElement("div");
31|  document.body.appendChild(container);
32|  act(() => {
33|    root = createRoot(container);
34|  });
35|  act(() => {
36|    root?.render(<HomeSpread />);
37|  });
38|});
39|
40|afterEach(() => {
41|  act(() => {
42|    root?.unmount();
43|  });
44|  root = null;
45|  container.remove();
46|});
47|
48|describe("shelf links", () => {
49|  test("each ready book starts reading at /read/<id>", () => {
50|    const ready = shelf.filter((book) => book.ready);
51|    expect(ready.length).toBeGreaterThan(0);
52|    for (const book of ready) {
53|      click(shelfButton(book.id));
54|      const link = container.querySelector("a.ob-read");
55|      expect(link?.getAttribute("href")).toBe(`/read/${book.id}`);
56|    }
57|  });
58|
59|  test("every book on the shelf opens its own reader", () => {
60|    expect(shelf.every((book) => book.ready)).toBe(true);
61|    for (const book of shelf) {
62|      click(shelfButton(book.id));
63|      expect(container.querySelector(".ob-cta-soon")).toBeNull();
64|      expect(container.querySelector("a.ob-read")?.getAttribute("href")).toBe(`/read/${book.id}`);
65|    }
66|  });
67|});

